import { readdirSync, readFileSync } from 'node:fs';
import { join, relative, resolve } from 'node:path';
import { expect, test } from '@playwright/test';
import { Validator } from '@seriousme/openapi-schema-validator';
import { elements } from '../../packages/core/meta/elements';
import { customElementsManifest } from '../../scripts/element-manifest';

// The site's read-only endpoints for agents: /openapi.json (generated by
// apps/site/src/lib/agent-api.ts), the RFC 9727 API catalog and the Custom
// Elements Manifest. The JSON errors come from Vercel's middleware; their
// tests are in scripts/site-markdown.test.ts.

const root = resolve(import.meta.dirname, '../..');
const dist = resolve(root, 'apps/site/dist');
const vercel = JSON.parse(
  readFileSync(resolve(root, 'apps/site/vercel.json'), 'utf8'),
) as {
  headers: { source: string; headers: { key: string; value: string }[] }[];
};
const headersFor = (source: string) =>
  Object.fromEntries(
    (vercel.headers.find((rule) => rule.source === source)?.headers ?? []).map(
      ({ key, value }) => [key.toLowerCase(), value],
    ),
  );

interface Operation {
  operationId: string;
  summary?: string;
  description?: string;
  parameters?: {
    name: string;
    in: string;
    description?: string;
    schema: { type: string; enum?: string[] };
  }[];
  responses: Record<string, { content?: Record<string, { schema?: object }> }>;
}
type Spec = { paths: Record<string, { get: Operation }> };

/** Every URL an operation describes: each value of its path parameter. */
function urls(path: string, operation: Operation): string[] {
  const [parameter] = operation.parameters ?? [];
  if (!parameter) return [path];
  return (parameter.schema.enum ?? []).map((value) =>
    path.replace(`{${parameter.name}}`, value),
  );
}

test('/openapi.json is a valid OpenAPI 3.1 document', async ({ request }) => {
  const response = await request.get('/openapi.json');
  expect(response.ok()).toBe(true);
  const spec = await response.json();
  const validator = new Validator();
  const result = await validator.validate(spec);
  expect(result.errors ?? []).toEqual([]);
  expect(result.valid).toBe(true);
  expect(validator.version).toBe('3.1');
  // Served with OpenAPI's own media type on Vercel.
  expect(headersFor('/openapi.json')['content-type']).toBe(
    'application/vnd.oai.openapi+json;version=3.1',
  );
});

test('every operation is self-describing, for function calling', async ({
  request,
}) => {
  const spec = (await (await request.get('/openapi.json')).json()) as Spec;
  const operations = Object.values(spec.paths).map((item) => item.get);
  expect(operations.length).toBeGreaterThan(5);
  const ids = operations.map((operation) => operation.operationId);
  expect(new Set(ids).size).toBe(ids.length);
  for (const operation of operations) {
    expect(operation.operationId).toMatch(/^[a-zA-Z][a-zA-Z0-9]*$/);
    expect(operation.summary, operation.operationId).toBeTruthy();
    expect(operation.description, operation.operationId).toBeTruthy();
    for (const parameter of operation.parameters ?? []) {
      expect(parameter.description, operation.operationId).toBeTruthy();
      expect(parameter.schema.type).toBe('string');
      expect(parameter.schema.enum?.length).toBeGreaterThan(0);
    }
    const ok = operation.responses['200']?.content ?? {};
    expect(Object.keys(ok), operation.operationId).toHaveLength(1);
    for (const media of Object.values(ok)) expect(media.schema).toBeTruthy();
  }
});

test('every operation documents its errors as RFC 9457 problems', async ({
  request,
}) => {
  const spec = (await (await request.get('/openapi.json')).json()) as Spec & {
    components: {
      schemas: { Problem: { properties: { code: { enum: string[] } } } };
    };
  };
  for (const [path, { get }] of Object.entries(spec.paths))
    expect(
      get.responses['404']?.content?.['application/problem+json']?.schema,
      path,
    ).toEqual({ $ref: '#/components/schemas/Problem' });
  expect(spec.components.schemas.Problem.properties.code.enum).toEqual([
    'page_not_found',
    'method_not_allowed',
  ]);
});

test('every URL the description lists answers, with the type it says', async ({
  request,
}) => {
  const spec = (await (await request.get('/openapi.json')).json()) as Spec;
  for (const [path, { get: operation }] of Object.entries(spec.paths)) {
    const [type = ''] = Object.keys(operation.responses['200']?.content ?? {});
    for (const url of urls(path, operation)) {
      const response = await request.get(url);
      expect(response.status(), url).toBe(200);
      expect(response.headers()['content-type'], url).toContain(type);
    }
  }
});

test('the description lists every Markdown copy on the site', async ({
  request,
}) => {
  const spec = (await (await request.get('/openapi.json')).json()) as Spec;
  const described = new Set(
    Object.entries(spec.paths).flatMap(([path, { get }]) => urls(path, get)),
  );
  const files = (dir: string): string[] =>
    readdirSync(dir, { withFileTypes: true }).flatMap((entry) =>
      entry.isDirectory()
        ? files(join(dir, entry.name))
        : [`/${relative(dist, join(dir, entry.name))}`],
    );
  const markdown = files(dist).filter((path) => path.endsWith('.md'));
  expect(markdown.length).toBeGreaterThan(20);
  expect(markdown.filter((path) => !described.has(path))).toEqual([]);
});

test('/custom-elements.json is the manifest the dotquilt package ships', async ({
  request,
}) => {
  const response = await request.get('/custom-elements.json');
  expect(response.ok()).toBe(true);
  const manifest = await response.json();
  expect(manifest).toEqual(
    JSON.parse(JSON.stringify(customElementsManifest(elements))),
  );
  expect(manifest.schemaVersion).toMatch(/^2\./);
});

test('the RFC 9727 API catalog links the OpenAPI description', async ({
  page,
  request,
}) => {
  const response = await request.get('/.well-known/api-catalog');
  expect(response.ok()).toBe(true);
  // RFC 9264 Linkset JSON: link context objects with an anchor and arrays
  // of target objects with an href.
  const { linkset } = JSON.parse(await response.text()) as {
    linkset: Record<string, string | { href: string; type?: string }[]>[];
  };
  for (const context of linkset) {
    expect(typeof context.anchor).toBe('string');
    for (const [relation, targets] of Object.entries(context))
      if (relation !== 'anchor')
        for (const target of targets as { href: string }[])
          expect(target.href).toMatch(/^https:\/\/dotquilt\.dev\//);
  }
  expect(linkset).toContainEqual({
    anchor: 'https://dotquilt.dev/.well-known/api-catalog',
    item: [{ href: 'https://dotquilt.dev/' }],
  });
  const api = linkset.find(
    (context) => context.anchor === 'https://dotquilt.dev/',
  );
  expect(api?.['service-desc']).toEqual([
    {
      href: 'https://dotquilt.dev/openapi.json',
      type: 'application/vnd.oai.openapi+json;version=3.1',
    },
  ]);
  // Its human docs, at a heading that exists.
  const [doc] = (api?.['service-doc'] ?? []) as { href: string }[];
  const url = new URL(doc?.href ?? '');
  await page.goto(url.pathname);
  await expect(page.locator(url.hash)).toBeVisible();
  // The errors' type, too.
  await expect(page.locator('#errors')).toBeVisible();

  // Vercel serves it as a Linkset with the RFC 9727 profile, and a HEAD
  // request gets the api-catalog Link header. These vercel.json headers
  // apply only without `trailingSlash`, which stops Vercel's routing for
  // /.well-known/ before any header (the middleware owns slashes instead).
  expect(vercel).not.toHaveProperty('trailingSlash');
  const headers = headersFor('/.well-known/api-catalog');
  expect(headers['content-type']).toBe(
    'application/linkset+json; profile="https://www.rfc-editor.org/info/rfc9727"',
  );
  expect(headers.link).toContain(
    '<https://dotquilt.dev/.well-known/api-catalog>; rel="api-catalog"',
  );
  expect(headers.link).toContain(
    '<https://dotquilt.dev/openapi.json>; rel="service-desc"',
  );
});

test('pages and llms.txt point agents to the catalog and the files', async ({
  page,
  request,
}) => {
  for (const path of ['/', '/docs/'] as const) {
    await page.goto(path);
    await expect(page.locator('head link[rel="api-catalog"]')).toHaveAttribute(
      'href',
      '/.well-known/api-catalog',
    );
  }
  const index = await (await request.get('/llms.txt')).text();
  expect(index).toContain('(https://dotquilt.dev/openapi.json)');
  expect(index).toContain('(https://dotquilt.dev/custom-elements.json)');
});
